  "stem": "다음 보기가 발문의 정답인가? (O/X)",
  "context": "다음 중 맞춤형화장품 조제관리사가 칭량(계량) 시 저울 위에 유황 분말 2g을 올릴 때, 칭량 오차를 줄이기 위해 저울의 원형 유리 돔(바람막이)을 닫는 주된 이유는?",
  "statement": "유황 냄새를 차단하기 위해",
  "truth": false,
  "mode": "answer",
  "sid": "understanding_st_4b521d",
  "derivedFrom": "subject4_q33#1",
  "explain": "📖 법령 근거 (교재: L593):\n| 제5조<br>영업자의 의무 등 🎯 기출 | • 화장품제조업자는 화장품의 제조와 관련된 기록·시설·기구 등 관리 방법, 원료·자재·완제품 등에 대한 시험·검사·검정 실시 방법 및 의무 등에 관하여 총리령으로 정하는 사항을 준수해야 함<br>• 화장품책임판매업자는 화장품의 품질관리기준, 책임판매 후 안전관리기준, 품질 검사 방법 및 실시 의무, 안전성·유효성 관련 정보사항 등의 보고 및 안전대책 마련 의무 등에 관하여 총리령으로 정하는 사항을 준수해야 함<br>• 맞춤형화장품판매업자는 소비자에게 유통·판매되는 화장품을 임의로 혼합·소분하여서는 안 됨<br>• 맞춤형화장품판매업자는 맞춤형화장품 판매장 시설·기구의 관리 방법, 혼합·소분 안전관리기준의 준수 의무, 혼합·소분되는 내용물 및 원료에 대한 설명 의무, 안전성 관련 사항 보고 의무 등에 관하여 총리령으로 정하는 사항을 준수해야 함<br>• 화장품책임판매업자는 총리령으로 정하는 바에 따라 화장품의 생산실적 또는 수입실적, 화장품의 제조과정에 사용된 원료의 목록 등을 식품의약품안전처장에게 보고하여야 함. 이 경우 원료의 목록에 관한 보고는 화장품의 유통·판매 전에 해야 함<br>• 맞춤형화장품판매업자는 총리령으로 정하는 바에 따라 맞춤형화장품에 사용된 모든 원료의 목록을 매년 1회 식품의약품안전처장에게 보고해야 함<br>• 책임판매관리자 및 맞춤형화장품조제관리사는 화장품의 안전성 확보 및 품질관리에 관한 교육을 매년 받아야 함<br>• 식품의약품안전처장은 국민 건강상 위해를 방지하기 위해 필요하다고 인정하면 화장품제조업자, 화장품책임판매업자 및 맞춤형화장품판매업자에게 화장품 관련 법령 및 제도(화장품의 안전성 확보 및 품질관리에 관한 내용을 포함함)에 관한 교육을 받을 것을 명할 수 있음<br>• 교육을 받아야 하는 자가 둘 이상의 장소에서 화장품제조업, 화장품책임판매업 또는 맞춤형화장품판매업을 하는 경우에는 종업원 중에서 총리령으로 정하는 자를 책임자로 지정하여 교육을 받게 할 수 있음<br>• 교육의 실시 기관, 내용, 대상 및 교육비 등에 관하여 필요한 사항은 총리령으로 정함 |",
