  "derivedFrom": "subject4_q40#1",
  "explain": "📖 법령 근거 (교재: L593):\n| 제5조<br>영업자의 의무 등 🎯 기출 | • 화장품제조업자는 화장품의 제조와 관련된 기록·시설·기구 등 관리 방법, 원료·자재·완제품 등에 대한 시험·검사·검정 실시 방법 및 의무 등에 관하여 총리령으로 정하는 사항을 준수해야 함<br>• 화장품책임판매업자는 화장품의 품질관리기준, 책임판매 후 안전관리기준, 품질 검사 방법 및 실시 의무, 안전성·유효성 관련 정보사항 등의 보고 및 안전대책 마련 의무 등에 관하여 총리령으로 정하는 사항을 준수해야 함<br>• 맞춤형화장품판매업자는 소비자에게 유통·판매되는 화장품을 임의로 혼합·소분하여서는 안 됨<br>• 맞춤형화장품판매업자는 맞춤형화장품 판매장 시설·기구의 관리 방법, 혼합·소분 안전관리기준의 준수 의무, 혼합·소분되는 내용물 및 원료에 대한 설...\n⚠️ *인용 위치 자동검증 불가 — 근거가 부정확할 수 있습니다*",
