  "context": "피부의 진피층 내에 그물망 구조를 형성하여 피부의 장력과 탄력을 유지해 주는 콜라겐(교원섬유)과 엘라스틴(탄력섬유)을 직접 합성해 내는 핵심 세포명은?",
  "statement": "각질형성세포",
