  "sid": "understanding_st_163837",
  "derivedFrom": "subject4_q51#4",
  "explain": "📖 교재 근거 (교재: L1243):\n| 망상층(Reticular Layer) 🎯 기출 | • 진피의 대부분을 차지하는 그물 모양(망상구조)의 결합조직<br>• 교원섬유(콜라겐) 90%, 탄력섬유(엘라스틴) 1.5~4.7%, 기질로 구성됨<br>• 모세혈관은 거의 없으며, 림프관, 한선, 피지선, 신경 등이 존재함 |\n⚠️ *인용 위치 자동검증 불가 — 근거가 부정확할 수 있습니다*",
