  "derivedFrom": "subject4_q65#5",
  "explain": "📖 교재 근거 (교재: L688):\n수용액 내에 계면활성제의 농도가 증가하면 분자 간 집합체인 미셀을 형성한다. 미셀이 형성될 때 계면활성제의 농도를 임계미셀농도(CMC: Critical Micelle Concentration)라고 한다.",
