  "explain": "📖 교재 근거 (교재: L588):\n| 제3조의4<br>맞춤형화장품 조제관리사 자격시험 | • 화장품과 원료 등에 대해 식품의약품안전처장이 실시하는 자격시험에 합격해야 함<br>• 거짓이나 그 밖의 부정한 방법으로 자격시험에 응시한 사람 또는 자격시험에서 부정행위를 한 사람에 대하여는 그 자격시험을 정지시키거나 합격을 무효로 함. 이 경우 자격시험이 정지되거나 합격이 무효가 된 사람은 그 처분이 있은 날부터 3년간 자격시험에 응시 불가<br>• 자격시험의 관리 및 자격증 발급 등에 관한 업무를 효과적으로 수행하기 위해 필요한 전문인력과 시설을 갖춘 기관 또는 단체를 시험운영기관으로 지정하여 시험업무를 위탁할 수 있음<br>• 자격시험의 시기, 절차, 방법, 시험과목, 자격증의 발급, 시험운영기관의 지정 등 자격시험에 필요한 사항은 총리...\n⚠️ *인용 위치 자동검증 불가 — 근거가 부정확할 수 있습니다*",
