  "sid": "understanding_st_70ccb7",
  "derivedFrom": "subject4_q104#1",
  "explain": "📖 교재 근거 (교재: L606):\n| 제12조의2<br>맞춤형화장품 판매업자의 준수사항 🎯 기출 | • 맞춤형화장품 판매장 시설·기구를 정기적으로 점검하여 보건위생상 위해가 없도록 관리할 것<br>• 다음의 혼합·소분 안전관리기준을 준수할 것<br>&nbsp;&nbsp;- 혼합·소분 전에 혼합·소분에 사용되는 내용물 또는 원료에 대한 품질성적서를 확인할 것<br>&nbsp;&nbsp;- 혼합·소분 전에 손을 소독하거나 세정할 것(다만, 혼합·소분 시 일회용 장갑을 착용하는 경우에는 그렇지 않음)<br>&nbsp;&nbsp;- 혼합·소분 전에 혼합·소분된 제품을 담을 포장용기의 오염 여부를 확인할 것<br>&nbsp;&nbsp;- 혼합·소분에 사용되는 장비 또는 기구 등은 사용 전에 그 위생 상태를 점검하고, 사용 후에는 오염이 없도록 세척할 것<br>&nbsp;&nbsp;- 그 밖에 위의 내용들과 유사한 것으로서 혼합·소분의 안전을 위해 식품의약품안전처장이 정하여 고시하는 사항을 준수할 것<br>• 아래 내용이 포함된 맞춤형화장품 판매내역서(전자문서로 된 판매내역서를 포함함)를 작성·보관할 것<br>&nbsp;&nbsp;- 제조번호<br>&nbsp;&nbsp;- 사용기한 또는 개봉 후 사용기간<br>&nbsp;&nbsp;- 판매일자 및 판매량<br>• 맞춤형화장품 판매 시 다음 내용을 소비자에게 설명할 것<br>&nbsp;&nbsp;- 혼합·소분에 사용된 내용물·원료의 내용 및 특성<br>&nbsp;&nbsp;- 맞춤형화장품 사용 시의 주의사항<br>• 맞춤형화장품 사용과 관련된 부작용 발생사례에 대해서는 식품의약품안전처장이 정하여 고시하는 바에 따라 지체 없이 식품의약품안전처장에게 보고할 것 |",
