  "context": "피부의 표피층 구조 중 각질세포 외막(Cornified Envelope) 단백질 결합을 촉진하여 피부 장벽을 튼튼하게 유지하는 칼슘 의존성 효소는?",
  "statement": "트랜스글루타미나아제 (Transglutaminase)",
