  "explain": "📖 교재 근거 (교재: L592):\n| 제3조의8<br>맞춤형화장품 조제관리사 자격의 취소 | • 거짓이나 그 밖의 부정한 방법으로 맞춤형화장품조제관리사의 자격을 취득한 경우<br>• 맞춤형화장품조제관리사의 결격사유에 해당하는 경우(자격이 취소된 날부터 3년이 지나지 않은 자는 제외함)<br>• 자격증 대여 등의 금지행위를 위반하여 다른 사람에게 자기의 성명을 사용하여 맞춤형화장품조제관리사 업무를 하게 하거나 맞춤형화장품조제관리사자격증을 양도 또는 대여한 경우 |\n⚠️ *인용 위치 자동검증 불가 — 근거가 부정확할 수 있습니다*",
