  "explain": "📖 교재 근거 (교재: L549):\n맞춤형화장품판매업으로 신고한 판매장에서 고객 개인별 피부 특성, 색, 향 등의 기호 및 요구를 반영하여 맞춤형화장품조제관리사 자격증을 가진 자가 아래의 내용으로 만든 화장품이다. 개성과 다양성을 추구하는 소비자 중심의 요구가 증가함에 따라 제품을 소비자의 특성 및 기호에 맞추어 혼합·소분(소량 생산 방식)하여 판매한다.\n⚠️ *인용 위치 자동검증 불가 — 근거가 부정확할 수 있습니다*",
