  "explain": "📖 교재 근거 (교재: L601):\n| 제8조의2<br>맞춤형화장품 판매업의 신고 🎯 기출 | • 소재지 관할 지방식품의약품안전청장에게 아래 ①, ②번 서류를 제출해야 함 (다만, 맞춤형화장품판매업자가 판매업소로 신고한 소재지 외의 장소에서 1개월 범위에서 한시적으로 같은 영업을 하려는 경우에는 ①번 서류에 ②, ③번 서류를 첨부하여 제출해야 함)<br>&nbsp;&nbsp;① 맞춤형화장품판매업 신고서(전자문서로 된 신고서 포함)<br>&nbsp;&nbsp;② 맞춤형화장품조제관리사 자격증 사본과 시설의 명세서<br>&nbsp;&nbsp;③ 맞춤형화장품판매업 신고필증 사본(전자문서로 발급받은 경우는 제외)<br>• 법인일 경우 지방식품의약품안전청장은 행정정보의 공동이용을 통해 법인 등기사항 증명서를 확인해야 함<br>• 지방식품의약품안전...\n⚠️ *인용 위치 자동검증 불가 — 근거가 부정확할 수 있습니다*",
