  "explain": "📖 교재 근거 (교재: L2961):\n> 해설: 맞춤형화장품 안전 기준에 따르면 소비자의 피부 상태나 선호도 등을 확인하지 아니하고 맞춤형화장품을 미리 혼합·소분하여 보관하거나 판매해서는 안 된다. 혼합·소분 전에는 손 소독·세정, 포장용기 오염 확인, 사용기한 확인 등이 필요하다.\n⚠️ *인용 위치 자동검증 불가 — 근거가 부정확할 수 있습니다*",
